INSERT INTO public.field_help (help_key, title, purpose, examples, format_notes, extra_notes, module_code)
VALUES
  ('public.project_briefs.document_status', 'Status', 'Where the brief stands in its approval: draft, submitted, approved or rejected.', '- Approved', NULL, NULL, 'wired_form_gaps'),
  ('public.project_mandates.version_number', 'Version', 'The version of this mandate. It goes up each time a changed mandate is saved.', '- 1.2', NULL, NULL, 'wired_form_gaps'),
  ('public.project_mandates.created_date', 'Created date', 'When the mandate was first written.', '- {example_date}', 'Dates show as {date_format}.', NULL, 'wired_form_gaps'),
  ('public.project_mandates.project_created_at', 'Project created', 'When a project was created from this mandate.', '- {example_date}', 'Dates show as {date_format}.', NULL, 'wired_form_gaps'),
  ('public.tasks.project_id', 'Project', 'The project this task belongs to.', '- Warehouse Upgrade', NULL, NULL, 'wired_form_gaps'),
  ('public.test_cases.test_steps', 'Test steps', 'The steps a tester follows, in order, with the result expected at each step.', '- 1. Open the login page. 2. Enter a valid user. Expected: the dashboard opens.', NULL, NULL, 'wired_form_gaps'),
  ('public.issue_reports.variable_impact', 'Impact', 'How the issue affects this area of the project (time, cost, quality, scope, risk or benefits).', '- Delays testing by two weeks; no change to cost.', NULL, NULL, 'wired_form_gaps'),
  ('public.exception_plans.option_description', 'Option description', 'What this recovery option would involve.', '- Add a second test team for four weeks.', NULL, NULL, 'wired_form_gaps'),
  ('public.exception_plans.option_pros_cons', 'Pros & cons', 'The main advantages and drawbacks of this option.', '- Pro: keeps the go-live date. Con: costs 40,000 more.', NULL, NULL, 'wired_form_gaps'),
  ('public.highlight_reports.six_variable_summary', 'Summary', 'Where this area stands this period, in a sentence or two.', '- Two weeks behind because of late supplier delivery.', NULL, NULL, 'wired_form_gaps'),
  ('public.highlight_reports.six_variable_forecast', 'Forecast', 'What you expect by the end of the stage.', '- Back on plan by the end of next month.', NULL, NULL, 'wired_form_gaps'),
  ('public.highlight_reports.escalation_required', 'Escalation required', 'Tick if a tolerance is forecast to be exceeded and the board must decide.', '- Ticked', NULL, NULL, 'wired_form_gaps'),
  ('public.portfolios.apply_field_template_inheritance', 'Apply inherited field template', 'Tick to give this portfolio the extra fields set for its parent level.', '- Ticked', NULL, NULL, 'wired_form_gaps'),
  ('public.programmes.apply_field_template_inheritance', 'Apply inherited field template', 'Tick to give this programme the extra fields set for its portfolio.', '- Ticked', NULL, NULL, 'wired_form_gaps'),
  ('public.issues.task_ids', 'Link to task', 'Tasks affected by this issue.', '- Install racking', NULL, NULL, 'wired_form_gaps'),
  ('public.issues.work_package_ids', 'Link to work package', 'Work packages affected by this issue.', '- Warehouse fit-out', NULL, NULL, 'wired_form_gaps'),
  ('public.issues.user_story_ids', 'Link to user story', 'User stories affected by this issue.', '- As a picker I can scan a shelf label', NULL, NULL, 'wired_form_gaps'),
  ('public.issues.kanban_card_ids', 'Link to Kanban card', 'Kanban cards affected by this issue.', '- Fix label printer', NULL, NULL, 'wired_form_gaps'),
  ('public.local_register_records.title', 'Title', 'A short name for this record. For a template, the title new records start with.', '- Server room access request', NULL, NULL, 'wired_form_gaps'),
  ('public.local_register_records.description', 'Description', 'More detail about the record.', '- Access needed for the weekend upgrade.', NULL, NULL, 'wired_form_gaps'),
  ('public.local_register_records.status', 'Status', 'Where the record stands.', '- Open', NULL, NULL, 'wired_form_gaps'),
  ('public.local_register_templates.template_name', 'Template name', 'A name for this template so people can find it when they add a record.', '- Weekend access request', NULL, NULL, 'wired_form_gaps'),
  ('public.local_register_templates.template_description', 'Template description', 'When to use this template.', '- Use for any out-of-hours access to the server room.', NULL, NULL, 'wired_form_gaps'),
  ('public.project_closures.closure_reason', 'Closure reason', 'Why the project is closing. One reason per line.', '- All products delivered and accepted', NULL, NULL, 'wired_form_gaps'),
  ('public.project_closures.performance_summary', 'Performance summary', 'How the project did against its plan, one point per line.', '- Finished two weeks late and 3% under budget', NULL, NULL, 'wired_form_gaps'),
  ('public.project_closures.benefits_realization_summary', 'Benefits realisation summary', 'Benefits achieved so far and those still to come.', '- Faster picking already seen; cost saving expected next year', NULL, NULL, 'wired_form_gaps'),
  ('public.project_closures.financial_closure_summary', 'Financial closure summary', 'The final financial position and what is left to close.', '- All invoices paid; two purchase orders to close', NULL, NULL, 'wired_form_gaps'),
