  ('public.lessons_reports.cost_performance_review', 'Cost / budget performance', 'How the project did against its budget, and why.', '- 3% under budget; contingency not used.', NULL, NULL, 'wired_form_gaps'),
  ('public.lessons_reports.quality_performance_review', 'Quality performance', 'Whether the products met their quality criteria.', '- All products passed first time except the label printer.', NULL, NULL, 'wired_form_gaps'),
