  ('public.lessons_reports.benefits_performance_review', 'Benefits realisation performance', 'Progress towards the expected benefits.', '- Picking time down 15% against a 20% target.', NULL, NULL, 'wired_form_gaps'),
  ('public.regional_format_local_field_definitions.label', 'Label', 'The name people see for your new setting.', '- Cost centre', NULL, NULL, 'wired_form_gaps'),
  ('public.regional_format_local_field_definitions.field_key', 'Key', 'A short unique code for the setting, used behind the scenes.', '- cost_centre', 'Lower case letters, numbers and underscores.', NULL, 'wired_form_gaps'),
