  ('public.organisation_regional_format_settings.number_grouping', 'Number grouping', 'How large numbers are grouped.', '- 1,234,567.89', NULL, NULL, 'wired_form_gaps'),
  ('public.organisation_regional_format_settings.first_day_of_week', 'First day of week', 'The day calendars and weekly views start on.', '- Monday', NULL, NULL, 'wired_form_gaps'),
  ('public.organisation_regional_format_settings.locale', 'Display locale', 'The language and region style used for names of months and days.', '- English (United Kingdom)', NULL, NULL, 'wired_form_gaps'),
  ('public.organisation_regional_format_settings.time_format', 'Time format', 'Whether times use a 12-hour or 24-hour clock.', '- 24-hour', NULL, NULL, 'wired_form_gaps'),
  ('public.organisation_regional_format_settings.fiscal_year_start_month', 'Fiscal year start month', 'The month your financial year starts.', '- April', NULL, NULL, 'wired_form_gaps'),
  ('public.organisation_regional_format_settings.negative_number_style', 'Negative number style', 'How negative amounts are shown.', '- (1,234.00)', NULL, NULL, 'wired_form_gaps'),
  ('public.organisation_regional_format_settings.percent_decimals', 'Percent decimals', 'How many decimal places percentages show.', '- 1', NULL, NULL, 'wired_form_gaps'),
  ('public.quality_register.quality_responsibilities', 'Quality responsibilities', 'Who carries out and approves each quality check.', '- Reviewer: Quality Lead; approver: Senior User', NULL, NULL, 'wired_form_gaps'),
  ('public.quality_register.quality_criteria', 'Quality criteria', 'The standards the product must meet.', '- No critical defects; meets the style guide', NULL, NULL, 'wired_form_gaps'),
